"""Build a self-contained dark report from retained observations, without rerunning experiments."""
import html
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
training=json.loads((ROOT/'docs/training-comparison.json').read_text())
generation=json.loads((ROOT/'docs/generation-comparison.json').read_text())
legacy=json.loads((ROOT/'docs/legacy-evidence.json').read_text())
runs=training['runs']
colors=['#83b9e9','#b6a0e9','#8cc9b4']
names=['Original · 400 steps','Compact · 400 steps','Compact · 800 steps']

def bars(values,unit,maximum):
    pieces=['<svg viewBox="0 0 520 215" role="img" aria-label="'+html.escape('; '.join(f'{n}: {v:.3f} {unit}' for n,v in zip(names,values)))+'">']
    for i,(value,color,name) in enumerate(zip(values,colors,names)):
        y=20+i*67
        pieces.append(f'<text x="0" y="{y}" fill="#aab6cb" font-size="12">{name}</text><rect x="0" y="{y+12}" width="{value/maximum*420:.1f}" height="12" rx="3" fill="{color}"/><text x="{value/maximum*420+10:.1f}" y="{y+23}" fill="#e7ebf3" font-size="12">{value:.2f}</text>')
    return ''.join(pieces)+'</svg>'

def learning(model):
    values=model['metadata']['training_metadata']['val_loss_history']
    # Historical logs recorded an initial evaluation and subsequent evaluations every 50 iterations.
    points=' '.join(f'{18+i/(len(values)-1)*484:.1f},{125-(v-2)/10*108:.1f}' for i,v in enumerate(values))
    return f'<svg viewBox="0 0 520 155" role="img" aria-label="Historical validation loss for {html.escape(model["name"])}"><path d="M18 125H502 M18 75H502 M18 25H502" stroke="#252e3e"/><polyline points="{points}" fill="none" stroke="#b6a0e9" stroke-width="2.2"/><text x="18" y="148" fill="#8a96ac" font-size="10">Recorded evaluations →</text></svg>'

rows=''.join(f'<tr><td>{name}</td><td>{r["summary"]["parameters"]/1e6:.3f}M</td><td>{r["summary"]["training_seconds"]:.2f}s</td><td>{r["summary"]["elapsed"]:.2f}s</td><td>{r["summary"]["test"]["bits_per_byte"]:.3f}</td></tr>' for name,r in zip(names,runs))
original_cards=''.join(f'<article><span class="eyebrow">{m["metadata"]["params"]/1e6:.1f}M parameters</span><h3>{html.escape(m["name"])}</h3>{learning(m)}<p>Historical best validation: <strong>{m["metadata"]["training_metadata"]["best_val_loss"]:.3f}</strong> at step {m["metadata"]["training_metadata"]["best_val_loss_step"]:,}. Validation loss is not a coherence score.</p></article>' for m in legacy['models'])
samples=''
for item in generation['samples']:
    samples+=f'<details><summary>{html.escape(item["prompt"].replace(chr(10)," "))} · seed {item["seed"]}</summary><div class="sample-grid">'
    for key,label in [('baseline','Original sampling'),('controlled','Penalty only · default'),('guarded','Penalty + hard phrase guard')]:
        sample=item[key]
        samples+=f'<article><h3>{label}</h3><small>{sample["repeat_fraction"]*100:.1f}% repeated four-token phrases</small><pre>{html.escape(sample["text"])}</pre></article>'
    samples+='</div></details>'
report='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VV-GPT · An evolution of your own model</title><style>
:root{color-scheme:dark;font-family:-apple-system,BlinkMacSystemFont,"Avenir Next",sans-serif;background:#0b0e14;color:#e7ebf3}*{box-sizing:border-box}body{margin:0 auto;max-width:1160px;padding:54px 32px 64px}a{color:#b6a0e9}header{border-bottom:1px solid #232b3b;padding-bottom:35px;margin-bottom:34px}.eyebrow{font-size:11px;letter-spacing:1.4px;color:#b6a0e9;text-transform:uppercase}h1{font-size:44px;font-weight:500;line-height:1.16;letter-spacing:-1.8px;max-width:800px;margin:18px 0}h2{font-size:23px;font-weight:500;letter-spacing:-.5px;margin:0 0 12px}h3{font-size:15px;font-weight:550;margin:12px 0}p,li{color:#9daac0;font-size:13px;line-height:1.9}strong{color:#d7e0ef;font-weight:550}.lead{max-width:800px;font-size:15px}.grid,.original,.sample-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.original,.sample-grid{grid-template-columns:repeat(3,minmax(0,1fr))}article{padding:23px;background:#111620;border:1px solid #232b3b;border-radius:12px;min-width:0}article p{font-size:12px;margin-bottom:0}svg{width:100%;display:block;margin:16px 0 0}.number{font-size:45px;line-height:1.2;letter-spacing:-1.7px;color:#b6a0e9;margin:12px 0 8px}.number small{font-size:14px;letter-spacing:0;color:#8a96ac}section{margin:38px 0}.note{padding:19px 23px;border-left:2px solid #8cc9b4;background:#10171d;border-radius:0 8px 8px 0;margin:24px 0}.note p{margin:0}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;margin-top:23px;font-size:12px;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:14px 12px;border-bottom:1px solid #232b3b;white-space:nowrap}th{color:#8290a9;font-weight:450}td{color:#cad5e7}.fine{font-size:11px;color:#7d8da7}ul{padding-left:19px}li{margin:9px 0}details{border-top:1px solid #232b3b;padding:18px 0}summary{cursor:pointer;font-size:13px;color:#bac7dd}pre{font:11px/1.85 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;color:#aab9d0}small{color:#8393ad;font-size:10px}.sample-grid{margin-top:20px}footer{border-top:1px solid #232b3b;padding-top:24px;color:#65728a;font-size:11px;line-height:1.9}@media(max-width:750px){body{padding:30px 18px}.grid,.original,.sample-grid{grid-template-columns:1fr}h1{font-size:34px}h2{font-size:21px}article{padding:20px}}</style>
<header><span class="eyebrow">VV-GPT4 · Research &amp; design notes · 17 November 2026</span><h1>An evolution of<br>your own model.</h1><p class="lead">Your Transformer, your datasets, your learned weights. A simpler dark studio with more trustworthy training and clearer evidence about what actually helps.</p></header>
<section><h2>What you had already achieved</h2><p>You built a complete language-model training project: a custom decoder, data preparation, GPU training, checkpoints, text generation and a desktop launcher. The three existing model families contain weights you trained yourself.</p><div class="original">'''+original_cards+'''</div><p class="fine">Historical metadata from VV-GPT3. Separate datasets and run configurations mean these values are not a ranking across models. The original source and checkpoints are preserved.</p></section>
<section><h2>The training-speed experiment</h2><p>Same public Shakespeare text, Nano decoder, batch 8, context 128 and seed 42. A compact vocabulary reduces the work in the embedding and output layers.</p><div class="grid"><article><span class="eyebrow">Steady training step · milliseconds ↓</span><div class="number">2.06× <small>observed speed ratio</small></div>'''+bars([r['summary']['steady_ms_per_step'] for r in runs],'ms per step',55)+'''</article><article><span class="eyebrow">Common held-out text · lower is better</span><div class="number">2.708 <small>best test bits per byte</small></div>'''+bars([r['summary']['test']['bits_per_byte'] for r in runs],'bits per byte',3.05)+'''</article></div><div class="note"><p><strong>Faster did not mean better here.</strong> The compact model scored worse after 400 steps. Spending the saved time on 800 steps narrowed the gap, but did not close it. The original vocabulary remains the default; compact is an optional experiment.</p></div><div class="table-wrap"><table><thead><tr><th>Condition</th><th>Parameters</th><th>Active training</th><th>Run elapsed</th><th>Test bits/byte ↓</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><p class="fine">One seed and one corpus, short pilots only. The exploratory 800-step budget was chosen after observing the first timing. Preflight/tokenizer fitting and model/data initialization are outside these timings. Steady step time excludes the first ten steps, evaluation and saving. Test scores use the same 8,000-byte slice; different vocabularies cover different amounts of raw text in 128 tokens. Raw token losses are not comparable across vocabularies. These pilots are not replacements for your original trained models.</p></section>
<section><h2>Improvements grounded in the original code</h2><div class="grid"><article><h3>Keep the actual best model</h3><p>The original final-save path retained live tensors: later training could overwrite the supposed best weights. All three final files differ from their separate best checkpoints. The new worker immediately saves the real best weights and keeps a separate resumable state.</p></article><article><h3>Resume with the training state intact</h3><p>Current Torch rejected the original resume load, which could fall back to starting fresh. Restricted checkpoint loading, optimizer/RNG restoration and explicit errors now make resume dependable. The CPU regression reaches exactly the same weights after interruption.</p></article><article><h3>Preserve the information in your data</h3><p>Emoji, punctuation, Unicode and speaker labels survive preparation. Common WhatsApp AM/PM exports and multiline messages are handled. Raw decoded uploads stay beside prepared copies; compact tokenizers learn from the training split only.</p></article><article><h3>Make learning visible</h3><p>Training and validation curves use fixed batches with dropout disabled. A separate final test follows checkpoint selection. Hover values, training pace, elapsed time and a measurement table give the dark studio a practical purpose.</p></article></div></section>
<section><h2>Read the samples, not just the repetition score</h2><p>The same original Shakespeare best checkpoint was tested with three fixed public prompts, 200 generated tokens and matched seeds. The mild penalty produced mixed results. Hard phrase blocking produced zero repeated four-token phrases by construction, but broke recurring delimiters and speaker labels. It is therefore opt-in.</p><p><strong>Better coherence is not yet demonstrated.</strong> Sampling controls cannot supply grammar, knowledge or conversational ability the model has not learned. Further quality work should use a fixed prompt set, more varied clean text, multiple seeds and a fresh held-out evaluation before claiming a better model.</p>'''+samples+'''</section>
<section><h2>Use the new studio</h2><p>Open <strong>VV-GPT4 Preview</strong> on your desktop. Training, Playground, Datasets and My models are the four main views. The original models appear alongside your new experiments. Advanced settings stay tucked away until needed.</p><p>All new work is local on <code>enhance-original-models</code>. The earlier assistant alpha is retained on <code>archive/assistant-alpha</code>. The original VV-GPT3 launcher and files remain unchanged.</p></section>
<footer>Evidence: docs/legacy-evidence.json · docs/training-comparison.json · docs/generation-comparison.json<br>Source lineage: XavierB100/vv-gpt3 @ 802d1a8 · Custom Transformer retained · No pretrained model weights</footer></html>'''
(ROOT/'docs/enhancements.html').write_text(report)
print('Built docs/enhancements.html from retained evidence.')
